// === Tab: mySketch ===
// https://de.wikipedia.org/wiki/Algorithmus_von_Prim

const animMode = true;
const raster = 100;
let pal; // see setup()

let pts = [];
let graph = [];
let queue = [];
let edges = [];
let marked = [];
let bars = [];
let state = 0;

function setup() {
	const wh = max(windowWidth, windowHeight);
	createCanvas(wh, wh);
	pixelDensity(1);
	frameRate(60);
	background(212);

	pal = ["white", color(192, 32, 160), color(32, 192, 160), color(192, 160, 32)];

	state = 0;
	pts = [];
	graph = [];
	queue = [];
	edges = [];
	marked = [];

	// init points
	const num = floor(width * height * 0.0005);
	if (false) {
		// random points in raster
		for (let i = 0; i < num; i++) {
			const x = floor(random(width * 0.1, width * 0.9) / raster) * raster;
			const y = floor(random(height * 0.1, height * 0.9) / raster) * raster;
			let insertPt = true;
			for (let p of pts) {
				if (dist(p.x, p.y, x, y) < 0.01) {
					insertPt = false;
					break;
				}
			}
			if (insertPt) pts.push({x, y});
		}
	} else {
		// ordered raster, shuffled
		for (let y = raster; y < height - raster; y += raster) {
			for (let x = raster; x < width - raster; x += raster) {
				if (random() < 0.75) pts.push({x, y});
			}
		}
		shuffle(pts, true);
	}

	// init queue with index of points
	for (let i = 0; i < pts.length; i++) queue.push(i);
	shuffle(queue, true);

	// init graph
	fromQueue2Graph(random(queue));
}

function fromQueue2Graph(idx, gidx = -1) {
	if (gidx >= 0) {
		edges.push({a: idx, b: gidx});
	}
	graph.push(idx);
	queue = queue.filter(function(e) {
		return e !== idx
	})
}

function draw() {
	background(0);

	// draw points
	if (true) {
		strokeWeight(4);
		pts.forEach((p, i) => {
			stroke(128, 64);
			point(p.x, p.y);
			noStroke()
			fill(32)
			if (false) text(i, p.x, p.y)
		})
	}

	// draw queue
	if (false) {
		strokeWeight(2);
		stroke(192, 32, 160);
		noFill();
		for (let node of queue) {
			const p = pts[node];
			circle(p.x, p.y, 6);
		}
	}

	// draw edges
	if (true) {
		strokeWeight(4);
		stroke(32, 64, 160);
		noFill();
		for (let edge of edges) {
			const p1 = pts[edge.a];
			const p2 = pts[edge.b];
			line(p1.x, p1.y, p2.x, p2.y);
		}
	}

	// draw graph
	if (false) {
		strokeWeight(2);
		stroke(32, 192, 160);
		noFill();
		for (let node of graph) {
			var p = pts[node];
			circle(p.x, p.y, 6);
		}
	}

	// drawMarked
	strokeWeight(6);
	stroke(196, 32, 80, 64);
	for (let i of marked) {
		var p1 = pts[i.a];
		var p2 = pts[i.b];
		line(p1.x, p1.y, p2.x, p2.y);
	}

	// seek for minimal spanning tree
	if (state === 0) {
		let finished = false;
		if (animMode) {
			if (queue.length !== 0) {
				proceedOnGraph();
			}	else {
				finished = true;
			}
		} else {
			while (queue.length !== 0) {
				proceedOnGraph();
			}	
			finished = true;
		} 

		if (finished) {
			edgesToBars(true);
			state = 1; // all bars are generated
		}

	} else if (state === 1) {
		// all bars generated
		state = 2;
		// prepare bars

	} else if (state === 2) {
		// show neon bars;
		background(0);
		noFill();
		strokeWeight(4);

		for (let b of bars) {
			drawBar(pts, b, random(pal));
		}

		// noLoop() removed for animation
	}

} // end draw()

function drawBar(pts, b, clr) {
	var p1 = pts[b.a];
	var p2 = pts[b.b];
	push();
	stroke(clr);
	drawingContext.shadowColor = clr;
	drawingContext.shadowBlur = raster*1.25;
	line(p1.x, p1.y, p2.x, p2.y);
	drawingContext.shadowBlur = raster;
	line(p1.x, p1.y, p2.x, p2.y);
	line(p1.x, p1.y, p2.x, p2.y);
	drawingContext.shadowBlur = raster*0.5;
	line(p1.x, p1.y, p2.x, p2.y);
	line(p1.x, p1.y, p2.x, p2.y);
	drawingContext.shadowBlur = raster*0.25;
	line(p1.x, p1.y, p2.x, p2.y);
	stroke(255);
	line(p1.x, p1.y, p2.x, p2.y);
	line(p1.x, p1.y, p2.x, p2.y);
	drawingContext.shadowBlur = 0;
	stroke(red(window.color(clr)), green(window.color(clr)), blue(window.color(clr)), 128);
	line(p1.x, p1.y, p2.x, p2.y);
	pop();
}

// ----------------------------------------------------------------------------------

function edgesToBars(debug) {
	bars = [];
	for (let i = 0; i < pts.length; i++) {
		var marked = getConnectedEdges(i);
		for (let m of marked) {
			let insertItem = true;
			for (let b of bars) {
				if ((m.a == b.a && m.b == b.b) || (m.a == b.b && m.b == b.a)) {
					insertItem = false; 
					break;
				}
			} 
			if (insertItem) bars.push(m);
		} 
	}

	if (debug) {
		console.clear();
		console.log("bars: " + bars.length + ", width/height: " + width + "/" + height);
		console.group("bars: " + bars.length);

		const colShader = [];
		for (let clr of pal) {
			colShader.push("vec3("+nf(red(window.color(clr))/255, 0, 2)+", "+nf(green(window.color(clr))/255, 0, 2)+", "+nf(blue(window.color(clr))/255, 0, 2)+")");
		}

		const minWH = max(width, height);
		for (let b of bars) {
			var p1 = pts[b.a];
			var p2 = pts[b.b];
			// console.log("[" + p1.x + ", " + p1.y + ", " + p2.x + ", " + p2.y + "],");
			// createBar(pos, 0.45, PI/2., .0, col, 0.005);
			console.log("bars[barIndex++] = createBar(vec2("+ pos2vec(b) + "), " + nf(dist(p1.x, p1.y, p2.x, p2.y)/minWH, 0, 2) + ", " + ang2float(b) + ", .0, " + random(colShader) + ", 0.005);"); //  + p1.x + ", " + p1.y + ", " + p2.x + ", " + p2.y + "],");
		}
		console.groupEnd();
		console.log("bars: " + bars.length);
	}
}

// convert position to shader vec2 -0.5 ... 0.5
function pos2vec(b) {
	var p1 = pts[b.a];
	var p2 = pts[b.b];
	let px = (p1.x+p2.x) * 0.5 / (floor(width/raster)*raster) - 0.5
	let py = -(p1.y+p2.y) * 0.5 / (floor(height/raster)*raster) + 0.5
	return "" + nf(px, 0, 4) + ", " + nf(py, 0, 4);
}
function ang2float(b) {
	var p1 = pts[b.a];
	var p2 = pts[b.b];
	let ang = createVector(p2.x-p1.x, p2.y-p1.y).heading();
	return "" + nf(ang, 0, 2);
}

// -----

function proceedOnGraph() {
	let g_idx = -1,
		q_idx = -1;
	let minDist = Infinity;

	shuffle(graph, true);
	shuffle(queue, true);

	for (let g_ref of graph) {
		for (let q_ref of queue) {
			let d = dist(pts[g_ref].x, pts[g_ref].y, pts[q_ref].x, pts[q_ref].y);
			if (d < minDist) {
				g_idx = g_ref;
				q_idx = q_ref;
				minDist = d;
			}
		}
	}
	if (g_idx >= 0 && q_idx >= 0) {
		fromQueue2Graph(q_idx, g_idx);
	}
}

function windowResized() {
	setup();
	loop();
}

function mousePressed() {
	if (mouseButton === LEFT) {
		setup(); loop();
		// markPosition((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))
	}
}

function markPosition(px, py) {
	marked = [];
	idx = -1;
	minDist = Infinity;
	pts.forEach((p, i) => {
		var d = dist(px, py, p.x, p.y);
		if (d < minDist) {
			minDist = d;
			idx = i;
		}
	})

	// when no pint found, return
	if (idx < 0) return;

	marked = getConnectedEdges(idx);
	for (let m of marked) {
		// console.log("marked : " + m.a + ", " + m.b);
	}
}

// by pts[idx]
function getConnectedEdges(idx) {
	// find connections
	res = [];
	let conns = getConnectedPoints(idx)
	for (let c of conns) {
		let end = traceConnPts([idx, c]);
		res.push({a: idx, b: end});
		// console.log(">conn1 : " + idx + ", " + end);
	}

	for (let j = res.length - 1; j > 0; j--) {
		for (let i = j - 1; i >= 0; i--) {
			let j_a = pts[res[j].a];
			let i_a = pts[res[i].a];
			if (j_a == i_a) {
				let j_b = pts[res[j].b];
				let i_b = pts[res[i].b];
				let j_ang = createVector(j_b.x - j_a.x, j_b.y - j_a.y).heading();
				let i_ang = createVector(i_b.x - i_a.x, i_b.y - i_a.y).heading();
				let d_ang = abs(j_ang + i_ang) % PI;
				if (d_ang < 0.01) {
					// console.log("da ("+res[j].a+"."+res[j].b+")/("+res[i].a+"."+res[i].b+") = " + d_ang);
					res[i].a = res[j].b;
					res[j].a = res[i].a;
					res[j].b = res[i].b;
					res.splice(j, 1);
					break;
				}
			}
		}
	}

	for (let c of res) {
		// console.log(">conn2 : " + c.a + ", " + c.b);
	}

	return res;
}

function getConnectedPoints(idx) {
	// console.log("getConnectedPoints(idx: " + idx + ")");

	// find connections
	let cpts = [];
	edges.forEach((e) => {
		if (e.a === idx) {
			cpts.push(e.b);
		}
		if (e.b === idx) {
			cpts.push(e.a);
		}
	})
	return cpts;
}

function traceConnPts(arr) {
	const idx = arr[0];
	const curr = arr[arr.length - 1];
	// console.log("traceConnPts(idx: " + idx + ", curr:" + curr + ")");

	let res = -1;
	let destAngle = createVector(pts[curr].x - pts[idx].x, pts[curr].y - pts[idx].y).heading();
	// console.log(">destAngle = " + destAngle);
	var conns = getConnectedPoints(curr);
	for (let next of conns) {
		if (!arr.includes(next)) {
			let currAngle = createVector(pts[next].x - pts[idx].x, pts[next].y - pts[idx].y).heading();
			// console.log(">currAngle = " + currAngle);
			if (abs(destAngle - currAngle) < 0.001) {
				res = traceConnPts([...arr, next]);
			}
		}
	}

	return res < 0 ? curr : res;
}
